"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78609"],{60084(e){e.exports=JSON.parse('{"id":"F102","slug":"credit-card-payoff","name":"Credit Card Payoff Time and Interest","subject":"Personal Finance","section":"Personal Finance","topic":"Credit cards and interest traps","level":"Beginner","aliases":["credit cards","minimum payment trap","card interest","months to pay off"],"formula":{"latex":"n=\\\\frac{-\\\\ln\\\\left(1-\\\\dfrac{iB}{P}\\\\right)}{\\\\ln(1+i)},\\\\quad P_{n}=\\\\frac{iB}{1-(1+i)^{-n}}","also":[],"text":"Months to pay off = -ln(1 - i x Balance / Payment) / ln(1 + i), where i is the monthly rate (APR / 12); Payment needed to clear in n months = i x Balance / (1 - (1 + i)^(-n))"},"symbols":[{"symbol":"B","meaning":"Card balance","unit":"money"},{"symbol":"i","meaning":"Monthly interest rate (APR / 12)","unit":"per month"},{"symbol":"P","meaning":"Fixed monthly payment","unit":"money"},{"symbol":"n","meaning":"Number of months","unit":"months"}],"when_to_use":"Use it to see the real cost of carrying a balance. If the payment is no more than one month of interest (i x B) the balance never falls. Paying only the minimum, which shrinks as the balance falls, takes far longer than a fixed payment. This assumes no new purchases and a constant rate; promotional rates change that.","worked_example":{"problem":"A card has a balance of 5,000 at 22% APR. You pay a fixed 200 a month. How long will it take, how much interest will you pay, and what payment would clear it in 24 months?","inputs":{"b":5000,"apr":22,"p":200,"tm":24},"steps":[{"label":"Monthly rate = APR / 12","working":"0.22 / 12","value":"1.833%"},{"label":"Months (exact) = -ln(1 - i B / P) / ln(1 + i)","working":"-ln(1-0.0183333 x 5000 / 200) / ln(1+0.0183333)","value":"33.75"},{"label":"Months rounded up","working":null,"value":"34"},{"label":"Final payment","working":"(5000 x (1+0.0183333)^(34-1)-200 x ((1+0.0183333)^(34-1)-1) / 0.0183333) x (1+0.0183333)","value":"149.88"},{"label":"Total paid = P x (m - 1) + final payment","working":"200 x (34-1)+last","value":"6,749.88"},{"label":"Total interest = total paid - balance","working":"6749.88-5000","value":"1,749.88"},{"label":"Payment to clear in the target months","working":"0.0183333 x 5000 / (1-(1+0.0183333)^(-24))","value":"259.39"},{"label":"Interest at that payment","working":"259.391 x 24-5000","value":"1,225.38"}],"answer":"With 200 a month it takes 34 months and you pay 1,749.88 in interest. To clear the balance in 24 months you would pay 259.39 a month, with 1,225.38 of interest."},"calculator":{"available":true,"inputs":[{"id":"b","label":"Card balance","unit":"money","type":"number","default":5000,"hint":""},{"id":"apr","label":"APR","unit":"%","type":"number","default":22,"hint":""},{"id":"p","label":"Fixed monthly payment","unit":"money","type":"number","default":200,"hint":""},{"id":"tm","label":"Target months to clear","unit":"months","type":"number","default":24,"hint":"","min":1}],"checks":[{"expr":"b>0 and apr>0 and p>b*apr/12","message":"The payment must be larger than one month of interest, or the balance never falls."}],"steps":[{"id":"i","label":"Monthly rate = APR / 12","expr":"apr/12","format":"pct3"},{"id":"nn","label":"Months (exact) = -ln(1 - i B / P) / ln(1 + i)","expr":"-ln(1-i*b/p)/ln(1+i)","format":"num2"},{"id":"m","label":"Months rounded up","expr":"ceil(nn)","format":"num0"},{"id":"last","label":"Final payment","expr":"(b*(1+i)^(m-1)-p*((1+i)^(m-1)-1)/i)*(1+i)","format":"money"},{"id":"tot","label":"Total paid = P x (m - 1) + final payment","expr":"p*(m-1)+last","format":"money"},{"id":"int","label":"Total interest = total paid - balance","expr":"tot-b","format":"money"},{"id":"p24","label":"Payment to clear in the target months","expr":"i*b/(1-(1+i)^(-tm))","format":"money"},{"id":"int24","label":"Interest at that payment","expr":"p24*tm-b","format":"money"}],"results":["m","int","p24"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"i":1.8333333333333333e-2,"nn":33.74768619437999,"m":34,"last":149.87945203599864,"tot":6749.879452035999,"int":1749.8794520359988,"p24":259.390773238679,"int24":1225.378557728296}},"finder":{"finds":"How long a card balance lasts and what it costs","needs":"Balance, APR, monthly payment"},"related":[{"slug":"credit-utilization","name":"Credit Utilization Ratio"},{"slug":"loan-payment","name":"Loan Payment (Amortization)"},{"slug":"ear","name":"Effective Annual Rate (EAR)"}],"related_ids":["F100","F031","F024"],"group":"Personal finance","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>n</mi><mo>=</mo><mfrac><mrow><mo>\u2212</mo><mi>ln</mi><mo>\u2061</mo><mrow><mo fence=\\"true\\">(</mo><mn>1</mn><mo>\u2212</mo><mfrac><mrow><mi>i</mi><mi>B</mi></mrow><mi>P</mi></mfrac><mo fence=\\"true\\">)</mo></mrow></mrow><mrow><mi>ln</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><mo stretchy=\\"false\\">)</mo></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>P</mi><mi>n</mi></msub><mo>=</mo><mfrac><mrow><mi>i</mi><mi>B</mi></mrow><mrow><mn>1</mn><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><msup><mo stretchy=\\"false\\">)</mo><mrow><mo>\u2212</mo><mi>n</mi></mrow></msup></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">n=\\\\frac{-\\\\ln\\\\left(1-\\\\dfrac{iB}{P}\\\\right)}{\\\\ln(1+i)},\\\\quad P_{n}=\\\\frac{iB}{1-(1+i)^{-n}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"cir-moments-feller","name":"Cox-Ingersoll-Ross Moments and Feller Condition"},"next":{"slug":"cds-spread-upfront","name":"Credit Default Swap: Spread, Upfront and Payout"},"lesson":null,"total":522}')}}]);